def resumo_intervalo(inicio, fim, excluidos=()):
    """conferencia aritmetica do intervalo (inclusive):
    dias corridos = uteis computados + uteis excluidos (dia do comeco) + dias uteis do
    recesso (suspensos, CPC art. 220) + feriados/dias sem expediente + sabados e domingos"""
    total = (fim - inicio).days + 1
    cat = {"uteis_computados": 0, "uteis_excluidos": 0, "suspensos": 0, "feriados": 0, "fds": 0}
    x = inicio
    while x <= fim:
        if x.weekday() >= 5:
            cat["fds"] += 1
        elif x in FERIADOS_CAMPINAS:
            cat["feriados"] += 1
        elif suspensa(x):
            cat["suspensos"] += 1
        elif x in excluidos:
            cat["uteis_excluidos"] += 1
        else:
            cat["uteis_computados"] += 1
        x += timedelta(days=1)
    assert sum(cat.values()) == total
    return total, cat

